/// Runner → server.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all_fields = "camelCase")]
pub enum RunnerMessage {
    /// First message on every connection, so a server that missed messages catches up.
    #[serde(rename = "hello")]
    Hello {
        runner_id: String,
        hostname: String,
        os: String,
        arch: String,
        version: String,
        #[serde(default)]
        sessions: Vec<LiveSession>,
        /// Sessions that ended since the last connection, causes included.
        #[serde(default)]
        ended: Vec<SessionEnd>,
    },
    #[serde(rename = "health")]
    Health {
        health: Health,
    },
    #[serde(rename = "session.opened")]
    SessionOpened {
        session: SessionInfo,
    },
    #[serde(rename = "session.error")]
    SessionError {
        id: Uuid,
        message: String,
    },
    #[serde(rename = "session.ended")]
    SessionEnded {
        end: SessionEnd,
    },
    #[serde(rename = "session.activity")]
    SessionActivity {
        id: Uuid,
        activity: Activity,
    },
    /// The screen and scrollback asked for by `session.replay`, as bytes that repaint a fresh terminal.
    #[serde(rename = "session.replay")]
    SessionReplay {
        id: Uuid,
        nonce: String,
        /// Base64.
        data: String,
    },
    #[serde(rename = "update.status")]
    UpdateStatus {
        state: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        version: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        message: Option<String>,
    },
    /// Plan usage readings that changed (all of them again on reconnect).
    #[serde(rename = "usage")]
    Usage {
        #[serde(default)]
        agents: Vec<AgentUsage>,
    },
    /// A session's latest spend reading (again on reconnect, and once more just before it ends).
    #[serde(rename = "session.cost")]
    SessionCost {
        cost: SessionCost,
    },
    /// A tool call from an agent in one of this runner's sessions (or `tools/list`, for its tools).
    #[serde(rename = "mcp.request")]
    McpRequest {
        req_id: String,
        session: Uuid,
        tool: String,
        args: serde_json::Value,
    },
    /// A task's worktree is made: where it came from.
    #[serde(rename = "task.started")]
    TaskStarted {
        task_id: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        repo: Option<String>,
        repo_dir: String,
        base: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        project: Option<String>,
    },
    #[serde(rename = "task.finished")]
    TaskFinished {
        task_id: String,
        ok: bool,
        /// app (a GitHub App token) or fallback (the machine's credentials).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pushed: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        owner: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        repo: Option<String>,
        branch: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        base: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        commit: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        reason: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        message: Option<String>,
    },
    /// What a task's branch changes against its base: line counts per file and the unified patch.
    #[serde(rename = "task.diff")]
    TaskDiff {
        task_id: String,
        ok: bool,
        #[serde(default)]
        files: Vec<DiffStat>,
        patch: String,
        truncated: bool,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        message: Option<String>,
    },
    #[serde(rename = "task.merged")]
    TaskMerged {
        task_id: String,
        ok: bool,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        commit: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        message: Option<String>,
    },
    /// How `task.handoff` went: the branch is on origin at `commit`, or `message` says why not.
    #[serde(rename = "task.handed_off")]
    TaskHandedOff {
        task_id: String,
        ok: bool,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pushed: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        commit: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        message: Option<String>,
    },
    /// What a draft's agent is doing (a `tool` line, the default) or saying (`text`).
    #[serde(rename = "draft.progress")]
    DraftProgress {
        id: String,
        text: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        kind: Option<DraftLineKind>,
    },
    /// A draft's agent finished: its last message, or why it couldn't.
    #[serde(rename = "draft.done")]
    DraftDone {
        id: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        output: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        error: Option<String>,
    },
    /// A line about setting a task's worktree up or cleaning it up (a worktree script starting or finishing), for its timeline.
    #[serde(rename = "task.progress")]
    TaskProgress {
        task_id: String,
        text: String,
    },
    #[serde(rename = "task.cleaned")]
    TaskCleaned {
        task_id: String,
        ok: bool,
        branch_deleted: bool,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        message: Option<String>,
    },
    /// A GitHub token to fetch or push a task's repo.
    #[serde(rename = "task.token_request")]
    TaskTokenRequest {
        req_id: String,
        task_id: String,
        owner: String,
        repo: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        purpose: Option<String>,
    },
    /// A repo's secrets: for a task assigned to this machine (`taskId`), or for its owner's own checkout (`maple-runner secrets pull`).
    #[serde(rename = "secrets.request")]
    SecretsRequest {
        req_id: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        task_id: Option<String>,
        /// GitHub owner/name.
        repo: String,
    },
}

/// Server → runner.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all_fields = "camelCase")]
pub enum ServerToRunner {
    #[serde(rename = "session.open")]
    SessionOpen {
        id: Uuid,
        agent: String,
        cwd: String,
        cols: u16,
        rows: u16,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        prompt: Option<String>,
        /// Continue the agent's last conversation in `cwd` (claude --resume / codex resume).
        resume: bool,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        task_id: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        worktree: Option<WorktreeSpec>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        task: Option<TaskStart>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        unattended: Option<Unattended>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        model: Option<String>,
    },
    #[serde(rename = "session.resize")]
    SessionResize {
        id: Uuid,
        cols: u16,
        rows: u16,
    },
    #[serde(rename = "session.kill")]
    SessionKill {
        id: Uuid,
    },
    /// Send the session's screen and scrollback, so a new viewer starts with what's there.
    #[serde(rename = "session.replay")]
    SessionReplay {
        id: Uuid,
        /// Echoed in the reply, so it goes to the viewer that asked.
        nonce: String,
    },
    #[serde(rename = "runner.update")]
    RunnerUpdate,
    #[serde(rename = "runner.restart")]
    RunnerRestart,
    /// The answer to `mcp.request`: `result` ({summary, data}) or `error`.
    #[serde(rename = "mcp.response")]
    McpResponse {
        req_id: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        result: Option<serde_json::Value>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        error: Option<String>,
    },
    /// Commit what's left in a task's worktree and push its branch.
    #[serde(rename = "task.finish")]
    TaskFinish {
        task_id: String,
        cwd: String,
        repo_dir: String,
        branch: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        base: Option<String>,
        title: String,
        /// Push with the machine's own credentials (no GitHub App).
        fallback: bool,
    },
    /// Report a task's diff against its base (answered with `task.diff`).
    #[serde(rename = "task.diff")]
    TaskDiff {
        task_id: String,
        cwd: String,
        base: String,
    },
    /// Merge a task's branch into its base on origin, for repos with no GitHub App.
    #[serde(rename = "task.merge")]
    TaskMerge {
        task_id: String,
        cwd: String,
        branch: String,
        base: String,
        title: String,
    },
    /// The task is moving to another machine: commit what its worktree has (as WIP) and push its branch.
    #[serde(rename = "task.handoff")]
    TaskHandoff {
        task_id: String,
        cwd: String,
        repo_dir: String,
        branch: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        base: Option<String>,
        title: String,
        fallback: bool,
    },
    /// Run Draft with AI's agent once, unable to change anything: with `repo` or `folder`, in a throwaway worktree of it made from GitHub's copy of `base` (then removed); else in an empty folder with no tools.
    #[serde(rename = "draft.run")]
    DraftRun {
        id: String,
        agent: String,
        prompt: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        repo: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        folder: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        base: Option<String>,
    },
    #[serde(rename = "draft.cancel")]
    DraftCancel {
        id: String,
    },
    /// Remove a finished task's worktree and local branch if nothing would be lost.
    #[serde(rename = "task.cleanup")]
    TaskCleanup {
        task_id: String,
        cwd: String,
        repo_dir: String,
        branch: String,
        merged: bool,
        #[serde(default)]
        heads: Vec<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        repo: Option<String>,
        /// The repo's worktree scripts: teardown runs first, and archive replaces the removal.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        scripts: Option<WorktreeScripts>,
    },
    /// The answer to `task.token_request`.
    #[serde(rename = "task.token")]
    TaskToken {
        req_id: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        token: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        error: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        code: Option<String>,
    },
    /// The answer to `secrets.request`: `values` by name, or `error` with a `code`.
    #[serde(rename = "secrets.reply")]
    SecretsReply {
        req_id: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        values: Option<BTreeMap<String, String>>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        error: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        code: Option<String>,
    },
}

